let result = $json;

// If AI Agent returns JSON inside "output"
if (result.output !== undefined) {
  if (typeof result.output === "string") {
    try {
      result = JSON.parse(result.output);
    } catch (error) {
      throw new Error(
        "AI Agent output is not valid JSON: " + result.output
      );
    }
  } else {
    result = result.output;
  }
}

// Make sure CGPA is a number
const cgpa = Number(result.cgpa);
const totalCredits = Number(result.totalCredits);
const semestersUsed = Number(result.semestersUsed);

if (!Number.isFinite(cgpa)) {
  throw new Error(
    "Invalid CGPA received from AI Agent: " + result.cgpa
  );
}

return [
  {
    json: {
      success: true,
      cgpa: cgpa,
      totalCredits: Number.isFinite(totalCredits)
        ? totalCredits
        : 0,
      semestersUsed: Number.isFinite(semestersUsed)
        ? semestersUsed
        : 0,
      message: "CGPA calculated successfully"
    }
  }
];

const input = $input.all();

return input.map((item, index) => {
  return {
    json: {
      itemNumber: index,
      rawData: item.json
    }
  };
});
